Algoritmo Productos
  Dimension nombres[3] Como Cadena;
  Dimension precios[3] Como Entero;
  Para i <- 0 Hasta 2 Hacer
    Leer nombres[i];
    Leer precios[i];
  FinPara
  Para i <- 0 Hasta 2 Hacer
    Escribir nombres[i], " ", precios[i];
  FinPara
FinAlgoritmo

